BEGIN;
CREATE SCHEMA gazi_ops;
SET LOCAL search_path=gazi_ops,pg_catalog;
CREATE TABLE users(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,phone text UNIQUE NOT NULL,name text NOT NULL,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('admin','seller')),active boolean NOT NULL DEFAULT true);
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id bigint NOT NULL REFERENCES users,csrf text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE login_attempts(key text PRIMARY KEY,count int NOT NULL,window_start timestamptz NOT NULL);
CREATE TABLE cities(code int PRIMARY KEY,name text UNIQUE NOT NULL);
CREATE TABLE districts(code int PRIMARY KEY,city_code int NOT NULL REFERENCES cities,name text NOT NULL,UNIQUE(city_code,name));
CREATE TABLE orders(
 siparis_no bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 seller_id bigint NOT NULL REFERENCES users,request_key uuid UNIQUE NOT NULL,
 source_order_no bigint UNIQUE,source_message_id text UNIQUE,
 ad_soyad text NOT NULL CHECK(length(trim(ad_soyad)) BETWEEN 2 AND 120),
 musteri_tel text NOT NULL CHECK(musteri_tel ~ '^90[0-9]{10}$'),siparis_tel text NOT NULL,
 siparis_alan text NOT NULL,adres text NOT NULL CHECK(length(trim(adres))>=5),
 sehir text NOT NULL CHECK(length(trim(sehir))>=2),ilce text NOT NULL CHECK(length(trim(ilce))>=2),
 sehir_kodu int,ilce_kodu int,urun_bilgisi text NOT NULL CHECK(length(trim(urun_bilgisi))>=2),
 toplam_tutar numeric(12,2) NOT NULL CHECK(toplam_tutar>=0),odeme_sekli text NOT NULL DEFAULT 'Kapıda ödeme',notlar text NOT NULL DEFAULT '',
 packages jsonb NOT NULL,kargo_adet int GENERATED ALWAYS AS (jsonb_array_length(packages)) STORED,
 kargo_durumu text NOT NULL DEFAULT 'Bekliyor' CHECK(kargo_durumu IN ('Bekliyor','Hazırlandı','Kargolandı','Tamamlandı','İade','İptal','Silindi')),
 tarih timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,
 iptal_nedeni text,iptal_tarihi timestamptz,merged_into bigint REFERENCES orders,cargo_attempt int NOT NULL DEFAULT 1
);
CREATE INDEX orders_status_no ON orders(kargo_durumu,siparis_no DESC);
CREATE INDEX orders_seller_no ON orders(seller_id,siparis_no DESC);
CREATE INDEX orders_phone_date ON orders(musteri_tel,tarih DESC);
CREATE INDEX orders_date ON orders(tarih);
CREATE TABLE shipments(order_id bigint PRIMARY KEY REFERENCES orders,reference text UNIQUE NOT NULL,tracking text UNIQUE,environment text NOT NULL CHECK(environment IN ('mock','sandbox','live')),status_code int,state text,state_at timestamptz,last_sync timestamptz,branch text,branch_phone text,cancelled_at timestamptz);
CREATE TABLE labels(order_id bigint PRIMARY KEY REFERENCES orders,zpl text,pdf_base64 text,barcodes jsonb NOT NULL DEFAULT '[]',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,order_id bigint NOT NULL REFERENCES orders,event_key text NOT NULL,title text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),actor_id bigint REFERENCES users,payload jsonb NOT NULL DEFAULT '{}',UNIQUE(order_id,event_key));
CREATE INDEX events_order_date ON events(order_id,occurred_at DESC,id DESC);
CREATE TABLE issues(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,order_id bigint NOT NULL REFERENCES orders,kind text NOT NULL,title text NOT NULL,state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','resolved')),resolution text,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE UNIQUE INDEX issues_open ON issues(order_id,kind) WHERE state='open';
CREATE TABLE jobs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,order_id bigint NOT NULL REFERENCES orders,kind text NOT NULL CHECK(kind IN ('create','track','label','cancel','codes','reaction')),payload jsonb NOT NULL DEFAULT '{}',state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','done','failed')),attempts int NOT NULL DEFAULT 0,run_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_token uuid,last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX jobs_active ON jobs(order_id,kind) WHERE state IN ('queued','running');
CREATE INDEX jobs_due ON jobs(run_at) WHERE state='queued';
CREATE TABLE shipment_archive(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,order_id bigint NOT NULL REFERENCES orders,payload jsonb NOT NULL,archived_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settings(key text PRIMARY KEY,value jsonb NOT NULL);
INSERT INTO settings VALUES('tracking_minutes','30'),('carrier_mode','"mock"');

CREATE FUNCTION phone(p text) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=gazi_ops,pg_catalog AS $$
DECLARE v text:=regexp_replace(coalesce(p,''),'[^0-9]','','g');
BEGIN
 IF left(v,2)='00' THEN v:=substr(v,3); END IF;
 IF length(v)=11 AND left(v,1)='0' THEN v:=substr(v,2); END IF;
 IF length(v)=10 THEN v:='90'||v; END IF;
 IF v !~ '^90[0-9]{10}$' THEN RAISE EXCEPTION 'Geçerli Türkiye telefon numarası girin'; END IF;
 RETURN v;
END $$;
CREATE FUNCTION validate_packages(p jsonb) RETURNS void LANGUAGE plpgsql SET search_path=gazi_ops,pg_catalog AS $$
DECLARE v jsonb;
BEGIN
 IF p IS NULL OR jsonb_typeof(p)<>'array' THEN RAISE EXCEPTION 'Paket listesi gerekli'; END IF;
 IF jsonb_array_length(p) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION '1–100 paket girin'; END IF;
 FOR v IN SELECT * FROM jsonb_array_elements(p) LOOP
  IF coalesce((v->>'kg')::numeric,0)<=0 OR coalesce((v->>'desi')::numeric,0)<=0 OR (v->>'kg')::numeric>1000 OR (v->>'desi')::numeric>1000 THEN RAISE EXCEPTION 'Her paket için geçerli KG ve desi girin'; END IF;
 END LOOP;
END $$;
CREATE FUNCTION actor(p_id bigint,p_admin boolean DEFAULT false) RETURNS users LANGUAGE plpgsql SET search_path=gazi_ops,pg_catalog AS $$
DECLARE u users;
BEGIN
 SELECT * INTO u FROM users WHERE id=p_id AND active;
 IF u.id IS NULL OR (p_admin AND u.role<>'admin') THEN RAISE EXCEPTION 'Bu işlem için yetkiniz yok'; END IF;
 RETURN u;
END $$;
CREATE FUNCTION queue(p_id bigint,p_kind text,p_payload jsonb DEFAULT '{}') RETURNS bigint LANGUAGE plpgsql SET search_path=gazi_ops,pg_catalog AS $$
DECLARE v bigint;
BEGIN
 INSERT INTO jobs(order_id,kind,payload) VALUES(p_id,p_kind,p_payload) ON CONFLICT(order_id,kind) WHERE state IN ('queued','running') DO NOTHING RETURNING id INTO v;
 IF v IS NULL THEN SELECT id INTO v FROM jobs WHERE order_id=p_id AND kind=p_kind AND state IN ('queued','running'); END IF;
 RETURN v;
END $$;
CREATE FUNCTION audit(p_id bigint,p_title text,p_actor bigint DEFAULT NULL,p_payload jsonb DEFAULT '{}') RETURNS void LANGUAGE plpgsql SET search_path=gazi_ops,pg_catalog AS $$
BEGIN
 INSERT INTO events(order_id,event_key,title,actor_id,payload) VALUES(p_id,'action:'||gen_random_uuid(),p_title,p_actor,p_payload);
END $$;
CREATE VIEW order_view WITH (security_invoker=true) AS
 SELECT o.*,s.reference AS kargo_referans,s.tracking AS kargo_takip_kodu,s.environment,s.status_code AS "shipmentStatusCode",s.state AS "shipmentStatus",coalesce(s.status_code=5,false) AS "isDelivered",s.last_sync AS kargo_gunc_saat,s.branch AS sube,s.branch_phone AS sube_tel,
 (SELECT sum((p->>'kg')::numeric) FROM jsonb_array_elements(o.packages) p) AS kargo_kg,
 EXISTS(SELECT 1 FROM labels l WHERE l.order_id=o.siparis_no AND (l.zpl IS NOT NULL OR l.pdf_base64 IS NOT NULL)) AS has_label,
 (SELECT count(*) FROM issues i WHERE i.order_id=o.siparis_no AND i.state='open') AS issue_count,
 (SELECT last_error FROM jobs j WHERE j.order_id=o.siparis_no AND j.state IN ('queued','failed') AND j.last_error IS NOT NULL ORDER BY id DESC LIMIT 1) AS gonder_hata_bilgisi,
 EXISTS(SELECT 1 FROM jobs j WHERE j.order_id=o.siparis_no AND j.state IN ('queued','running') AND kind IN ('create','cancel','label')) AS cargo_busy
 FROM orders o LEFT JOIN shipments s ON s.order_id=o.siparis_no;

-- The API passes the actor only after validating an HttpOnly session. No public SQL/RPC endpoint.
CREATE FUNCTION rpc(p_actor bigint,p_operation text,p_data jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SET search_path=gazi_ops,pg_catalog AS $$
DECLARE u users; seller users; o orders; other orders; v_id bigint; v_result jsonb; v_query text; v_tab text; v_filter text; v_rows jsonb; v_limit int; v_pkg jsonb; v_count int; v_job bigint; v_key uuid; v_code int;
BEGIN
 u:=actor(p_actor);v_id:=nullif(p_data->>'id','')::bigint;
 IF p_operation IN ('list','report','summary') THEN
  v_query:=trim(coalesce(p_data->>'query',''));v_tab:=coalesce(p_data->>'tab','all');v_filter:=coalesce(p_data->>'cargo_filter','all');v_limit:=least(200,greatest(1,coalesce((p_data->>'limit')::int,50)));
  IF p_operation='summary' THEN
   SELECT jsonb_build_object('total',count(*),'amount',coalesce(sum(toplam_tutar),0),'waiting',count(*) FILTER(WHERE kargo_durumu='Bekliyor'),'ready',count(*) FILTER(WHERE kargo_durumu='Hazırlandı'),'shipped',count(*) FILTER(WHERE kargo_durumu='Kargolandı'),'delivered',count(*) FILTER(WHERE kargo_durumu='Tamamlandı'),'support',count(*) FILTER(WHERE issue_count>0)) INTO v_result FROM order_view WHERE kargo_durumu<>'Silindi' AND (u.role='admin' OR seller_id=u.id);
   RETURN v_result;
  END IF;
  IF p_operation='report' AND nullif(p_data->>'start','')::date>nullif(p_data->>'end','')::date THEN RAISE EXCEPTION 'Başlangıç tarihi bitişten sonra olamaz'; END IF;
  WITH filtered AS (
   SELECT * FROM order_view WHERE (u.role='admin' OR seller_id=u.id) AND kargo_durumu<>'Silindi'
   AND (v_tab='all' OR (v_tab='bekleyen' AND kargo_durumu='Bekliyor') OR (v_tab='hazirlandi' AND kargo_durumu='Hazırlandı') OR (v_tab='kargolandi' AND kargo_durumu IN ('Kargolandı','Tamamlandı')) OR (v_tab='tamamlandi' AND "isDelivered") OR (v_tab='sorunlu' AND ("shipmentStatusCode" IN (6,7,8) OR kargo_durumu='İade')) OR (v_tab='iptal' AND kargo_durumu='İptal') OR (v_tab='destek' AND issue_count>0))
   AND (v_filter='all' OR (v_filter='created' AND "shipmentStatusCode"=1) OR (v_filter='transit' AND "shipmentStatusCode" IN (2,3)) OR (v_filter='delivery' AND "shipmentStatusCode"=4) OR (v_filter='delivered' AND "shipmentStatusCode"=5) OR (v_filter='problem' AND "shipmentStatusCode" IN (6,7,8)))
   AND (v_query='' OR position(lower(v_query) IN lower(concat_ws(' ',siparis_no,source_order_no,ad_soyad,adres,musteri_tel,siparis_tel,urun_bilgisi,kargo_takip_kodu,kargo_referans)))>0 OR (regexp_replace(v_query,'[^0-9]','','g')<>'' AND (position(regexp_replace(v_query,'[^0-9]','','g') IN musteri_tel)>0 OR position(regexp_replace(v_query,'[^0-9]','','g') IN siparis_tel)>0)))
   AND (nullif(p_data->>'start','') IS NULL OR tarih>=(p_data->>'start')::date::timestamp AT TIME ZONE 'Europe/Istanbul')
   AND (nullif(p_data->>'end','') IS NULL OR tarih<((p_data->>'end')::date+1)::timestamp AT TIME ZONE 'Europe/Istanbul')
  ), page AS (SELECT * FROM filtered WHERE nullif(p_data->>'before','') IS NULL OR siparis_no<(p_data->>'before')::bigint ORDER BY siparis_no DESC LIMIT v_limit+1)
  SELECT jsonb_build_object('total',(SELECT count(*) FROM filtered),'amount',(SELECT coalesce(sum(toplam_tutar),0) FROM filtered),'has_more',(SELECT count(*)>v_limit FROM page),'by_status',CASE WHEN p_operation='report' THEN (SELECT jsonb_agg(to_jsonb(z)) FROM (SELECT kargo_durumu AS name,count(*) AS count,coalesce(sum(toplam_tutar),0) AS amount FROM filtered GROUP BY kargo_durumu ORDER BY count(*) DESC) z) ELSE NULL END,'by_day',CASE WHEN p_operation='report' THEN (SELECT jsonb_agg(to_jsonb(z) ORDER BY day) FROM (SELECT (tarih AT TIME ZONE 'Europe/Istanbul')::date AS day,count(*) AS count,coalesce(sum(toplam_tutar),0) AS amount FROM filtered GROUP BY (tarih AT TIME ZONE 'Europe/Istanbul')::date) z) ELSE NULL END,'rows',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY siparis_no DESC) FROM (SELECT * FROM page LIMIT v_limit)x),'[]')) INTO v_result;
  RETURN v_result;
 ELSIF p_operation='cities' THEN
  SELECT coalesce(jsonb_agg(c ORDER BY name),'[]') INTO v_result FROM cities c;RETURN v_result;
 ELSIF p_operation='districts' THEN
  SELECT coalesce(jsonb_agg(d ORDER BY name),'[]') INTO v_result FROM districts d WHERE city_code=(p_data->>'city_code')::int;RETURN v_result;
 ELSIF p_operation='users' THEN
  PERFORM actor(p_actor,true);SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'phone',phone,'role',role) ORDER BY name),'[]') INTO v_result FROM users WHERE active;RETURN v_result;
 ELSIF p_operation='connection' THEN
  PERFORM actor(p_actor,true);RETURN jsonb_build_object('mode',(SELECT value FROM settings WHERE key='carrier_mode'),'tracking_minutes',(SELECT value FROM settings WHERE key='tracking_minutes'),'queued',(SELECT count(*) FROM jobs WHERE state IN ('queued','running')),'failed',(SELECT count(*) FROM jobs WHERE state='failed'),'last_worker',(SELECT max(occurred_at) FROM events WHERE event_key LIKE 'worker:%'));
 ELSIF p_operation='bulk_track' THEN
  PERFORM actor(p_actor,true);v_count:=0;
  FOR v_id IN SELECT sh.order_id FROM shipments sh JOIN orders ord ON ord.siparis_no=sh.order_id WHERE sh.cancelled_at IS NULL AND ord.kargo_durumu IN ('Kargolandı','İade') LOOP
   PERFORM queue(v_id,'track');v_count:=v_count+1;
  END LOOP;RETURN jsonb_build_object('queued',v_count);
 ELSIF p_operation='resolve' THEN
  PERFORM actor(p_actor,true);IF length(trim(coalesce(p_data->>'resolution','')))<3 THEN RAISE EXCEPTION 'Çözüm açıklaması girin'; END IF;
  UPDATE issues SET state='resolved',resolution=p_data->>'resolution',resolved_at=now() WHERE id=v_id AND state='open' RETURNING order_id INTO v_id;
  IF v_id IS NULL THEN RAISE EXCEPTION 'Açık sorun bulunamadı'; END IF;
  PERFORM audit(v_id,'Sorun çözüldü: '||(p_data->>'resolution'),p_actor);RETURN '{"ok":true}';
 ELSIF p_operation='create' THEN
  v_key:=(p_data->>'request_key')::uuid;IF v_key IS NULL THEN RAISE EXCEPTION 'İstek anahtarı gerekli'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(phone(p_data->>'musteri_tel'),0));
  SELECT * INTO o FROM orders WHERE request_key=v_key;
  IF FOUND THEN IF u.role<>'admin' AND o.seller_id<>u.id THEN RAISE EXCEPTION 'İstek anahtarı başka kullanıcıya ait'; END IF;RETURN jsonb_build_object('id',o.siparis_no,'replayed',true); END IF;
  v_pkg:=p_data->'packages';PERFORM validate_packages(v_pkg);
  v_id:=coalesce((p_data->>'seller_id')::bigint,u.id);IF u.role<>'admin' AND v_id<>u.id THEN RAISE EXCEPTION 'Başka satıcı adına sipariş açılamaz'; END IF;
  seller:=actor(v_id);
  INSERT INTO orders(seller_id,request_key,ad_soyad,musteri_tel,siparis_tel,siparis_alan,adres,sehir,ilce,sehir_kodu,ilce_kodu,urun_bilgisi,toplam_tutar,odeme_sekli,notlar,packages)
  VALUES(v_id,v_key,p_data->>'ad_soyad',phone(p_data->>'musteri_tel'),seller.phone,seller.name,p_data->>'adres',p_data->>'sehir',p_data->>'ilce',nullif(p_data->>'sehir_kodu','')::int,nullif(p_data->>'ilce_kodu','')::int,p_data->>'urun_bilgisi',(p_data->>'toplam_tutar')::numeric,coalesce(p_data->>'odeme_sekli','Kapıda ödeme'),coalesce(p_data->>'notlar',''),v_pkg) RETURNING siparis_no INTO v_id;
  PERFORM audit(v_id,'Sipariş oluşturuldu',p_actor);
  IF EXISTS(SELECT 1 FROM orders WHERE siparis_no<>v_id AND musteri_tel=phone(p_data->>'musteri_tel') AND seller_id=seller.id AND tarih>now()-interval '24 hours' AND kargo_durumu NOT IN ('Silindi','İptal','İade')) THEN
   INSERT INTO issues(order_id,kind,title) VALUES(v_id,'duplicate','Aynı müşteri telefonu ile son 24 saatte başka sipariş var');
  END IF;RETURN jsonb_build_object('id',v_id);
 END IF;
 -- Lock both merge candidates in a stable order to avoid deadlocks.
 IF p_operation='merge' THEN
  PERFORM actor(p_actor,true);PERFORM 1 FROM orders WHERE siparis_no IN (v_id,(p_data->>'target')::bigint) ORDER BY siparis_no FOR UPDATE;
 END IF;
 SELECT * INTO o FROM orders WHERE siparis_no=v_id AND (u.role='admin' OR seller_id=u.id) FOR UPDATE;
 IF o.siparis_no IS NULL THEN RAISE EXCEPTION 'Sipariş bulunamadı'; END IF;
 IF p_operation='detail' THEN
  SELECT jsonb_build_object('order',to_jsonb(v),'events',(SELECT coalesce(jsonb_agg(e ORDER BY occurred_at DESC,id DESC),'[]') FROM events e WHERE order_id=v_id),'issues',(SELECT coalesce(jsonb_agg(i ORDER BY id DESC),'[]') FROM issues i WHERE order_id=v_id),'jobs',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',j.id,'kind',kind,'state',state,'attempts',attempts,'last_error',last_error) ORDER BY id DESC),'[]') FROM jobs j WHERE order_id=v_id)) INTO v_result FROM order_view v WHERE siparis_no=v_id;RETURN v_result;
 ELSIF p_operation='label' THEN
  SELECT jsonb_build_object('zpl',zpl,'pdf_base64',pdf_base64,'barcodes',barcodes) INTO v_result FROM labels WHERE order_id=v_id;
  IF v_result IS NULL THEN RAISE EXCEPTION 'Kargo etiketi henüz oluşturulmadı'; END IF;RETURN v_result;
 ELSIF p_operation='duplicates' THEN
  PERFORM actor(p_actor,true);SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO v_result FROM order_view x WHERE siparis_no<>v_id AND kargo_durumu<>'Silindi' AND musteri_tel=o.musteri_tel AND seller_id=o.seller_id AND abs(extract(epoch FROM tarih-o.tarih))<=86400;RETURN v_result;
 END IF;
 IF EXISTS(SELECT 1 FROM jobs WHERE order_id=v_id AND kind IN ('create','cancel','label') AND state IN ('queued','running')) THEN RAISE EXCEPTION 'Kargo işlemi sürüyor; tamamlanmasını bekleyin'; END IF;
 IF p_operation IN ('edit','prepare','waiting','cancel','restore','hide','merge') AND o.version IS DISTINCT FROM (p_data->>'version')::int THEN RAISE EXCEPTION 'Kayıt değişti; siparişi yeniden açın'; END IF;
 IF p_operation='edit' THEN
  IF o.kargo_durumu<>'Bekliyor' THEN RAISE EXCEPTION 'Yalnızca bekleyen sipariş düzenlenebilir'; END IF;
  v_pkg:=p_data->'packages';PERFORM validate_packages(v_pkg);
  UPDATE orders SET ad_soyad=p_data->>'ad_soyad',musteri_tel=phone(p_data->>'musteri_tel'),adres=p_data->>'adres',sehir=p_data->>'sehir',ilce=p_data->>'ilce',sehir_kodu=nullif(p_data->>'sehir_kodu','')::int,ilce_kodu=nullif(p_data->>'ilce_kodu','')::int,urun_bilgisi=p_data->>'urun_bilgisi',toplam_tutar=(p_data->>'toplam_tutar')::numeric,odeme_sekli=coalesce(p_data->>'odeme_sekli',odeme_sekli),notlar=coalesce(p_data->>'notlar',''),packages=v_pkg,version=version+1,updated_at=now() WHERE siparis_no=v_id;
  PERFORM audit(v_id,'Sipariş düzenlendi',p_actor);
 ELSE
  PERFORM actor(p_actor,true);
  IF p_operation='prepare' THEN
   IF o.kargo_durumu<>'Bekliyor' THEN RAISE EXCEPTION 'Sipariş zaten hazırlanmış veya durum değişmiş'; END IF;
   PERFORM validate_packages(o.packages);UPDATE orders SET kargo_durumu='Hazırlandı',version=version+1,updated_at=now() WHERE siparis_no=v_id;
   PERFORM audit(v_id,'Sipariş hazırlandı; hazırlama etiketi oluşturuldu',p_actor);PERFORM queue(v_id,'reaction','{"emoji":"📦"}');
  ELSIF p_operation='waiting' THEN
   IF o.kargo_durumu<>'Hazırlandı' OR EXISTS(SELECT 1 FROM shipments WHERE order_id=v_id AND cancelled_at IS NULL) THEN RAISE EXCEPTION 'Kargo kaydı olan sipariş bekleyene alınamaz'; END IF;
   UPDATE orders SET kargo_durumu='Bekliyor',version=version+1,updated_at=now() WHERE siparis_no=v_id;PERFORM audit(v_id,'Bekleyene alındı',p_actor);
  ELSIF p_operation IN ('cargo','track','retry_label','codes') THEN
   IF p_operation='cargo' THEN
    IF EXISTS(SELECT 1 FROM shipments WHERE order_id=v_id AND cancelled_at IS NULL) THEN
     RETURN jsonb_build_object('job_id',queue(v_id,'label'),'already_created',true);
    END IF;
    IF o.kargo_durumu<>'Hazırlandı' THEN RAISE EXCEPTION 'Siparişi önce hazırlayın'; END IF;
   ELSIF p_operation IN ('track','retry_label') AND NOT EXISTS(SELECT 1 FROM shipments WHERE order_id=v_id AND cancelled_at IS NULL) THEN RAISE EXCEPTION 'Aktif kargo kaydı bulunamadı';
   ELSIF p_operation='codes' AND o.kargo_durumu NOT IN ('Bekliyor','Hazırlandı') THEN RAISE EXCEPTION 'Kargolanan siparişin adres kodu değiştirilemez'; END IF;
   v_job:=queue(v_id,CASE p_operation WHEN 'cargo' THEN 'create' WHEN 'retry_label' THEN 'label' ELSE p_operation END);RETURN jsonb_build_object('job_id',v_job);
  ELSIF p_operation='cancel' THEN
   IF o.kargo_durumu NOT IN ('Bekliyor','Hazırlandı','Kargolandı') THEN RAISE EXCEPTION 'Bu sipariş iptal edilemez'; END IF;
   IF length(trim(coalesce(p_data->>'reason','')))<3 THEN RAISE EXCEPTION 'İptal nedeni girin'; END IF;
   IF EXISTS(SELECT 1 FROM shipments WHERE order_id=v_id AND cancelled_at IS NULL) THEN RETURN jsonb_build_object('job_id',queue(v_id,'cancel',jsonb_build_object('reason',p_data->>'reason'))); END IF;
   UPDATE orders SET kargo_durumu='İptal',iptal_nedeni=p_data->>'reason',iptal_tarihi=now(),version=version+1,updated_at=now() WHERE siparis_no=v_id;PERFORM audit(v_id,'Sipariş iptal edildi',p_actor,p_data);
  ELSIF p_operation='restore' THEN
   IF o.kargo_durumu<>'İptal' THEN RAISE EXCEPTION 'Yalnızca iptal edilen sipariş geri alınabilir'; END IF;
   IF EXISTS(SELECT 1 FROM shipments WHERE order_id=v_id AND cancelled_at IS NULL) THEN RAISE EXCEPTION 'DHL iptali doğrulanmadı'; END IF;
   INSERT INTO shipment_archive(order_id,payload) SELECT v_id,jsonb_build_object('shipment',to_jsonb(s),'label',(SELECT to_jsonb(l) FROM labels l WHERE order_id=v_id)) FROM shipments s WHERE order_id=v_id;
   DELETE FROM labels WHERE order_id=v_id;DELETE FROM shipments WHERE order_id=v_id;
   UPDATE orders SET kargo_durumu='Bekliyor',cargo_attempt=cargo_attempt+1,iptal_nedeni=NULL,iptal_tarihi=NULL,version=version+1,updated_at=now() WHERE siparis_no=v_id;PERFORM audit(v_id,'İptal geri alındı; yeni gönderi referansı ayrıldı',p_actor);
  ELSIF p_operation='hide' THEN
   IF o.kargo_durumu<>'İptal' THEN RAISE EXCEPTION 'Yalnızca iptal edilen sipariş arşivlenebilir'; END IF;
   UPDATE orders SET kargo_durumu='Silindi',version=version+1,updated_at=now() WHERE siparis_no=v_id;PERFORM audit(v_id,'İptal kaydı listeden kaldırıldı',p_actor);
  ELSIF p_operation='merge' THEN
   SELECT * INTO other FROM orders WHERE siparis_no=(p_data->>'target')::bigint;
   IF other.siparis_no IS NULL OR other.siparis_no=v_id OR o.kargo_durumu<>'Bekliyor' OR other.kargo_durumu<>'Bekliyor' OR o.musteri_tel<>other.musteri_tel OR o.seller_id<>other.seller_id OR abs(extract(epoch FROM o.tarih-other.tarih))>86400 THEN RAISE EXCEPTION 'Yalnızca aynı satıcı/müşterinin 24 saat içindeki bekleyen kayıtları birleştirilebilir'; END IF;
   IF other.version IS DISTINCT FROM (p_data->>'target_version')::int OR EXISTS(SELECT 1 FROM shipments WHERE order_id IN (v_id,other.siparis_no)) OR EXISTS(SELECT 1 FROM jobs WHERE order_id=other.siparis_no AND state IN ('queued','running') AND kind IN ('create','cancel','label')) THEN RAISE EXCEPTION 'Hedef değişti veya kargo işlemi var'; END IF;
   UPDATE orders SET ad_soyad=o.ad_soyad,adres=o.adres,sehir=o.sehir,ilce=o.ilce,sehir_kodu=o.sehir_kodu,ilce_kodu=o.ilce_kodu,urun_bilgisi=o.urun_bilgisi,toplam_tutar=o.toplam_tutar,odeme_sekli=o.odeme_sekli,notlar=o.notlar,packages=o.packages,version=version+1,updated_at=now() WHERE siparis_no=other.siparis_no;
   UPDATE orders SET kargo_durumu='Silindi',merged_into=other.siparis_no,version=version+1,updated_at=now() WHERE siparis_no=v_id;
   UPDATE issues SET state='resolved',resolution='Birleştirildi',resolved_at=now() WHERE order_id IN (v_id,other.siparis_no) AND kind='duplicate' AND state='open';
   PERFORM audit(other.siparis_no,'Yeni kaydın bilgileriyle güncellendi; birleştirilen # '||v_id,p_actor,jsonb_build_object('source_snapshot',to_jsonb(o),'target_snapshot',to_jsonb(other)));
   PERFORM audit(v_id,'Birleştirildi: #'||other.siparis_no,p_actor);
  ELSE RAISE EXCEPTION 'Geçersiz işlem'; END IF;
 END IF;
 RETURN '{"ok":true}';
END $$;

CREATE FUNCTION schedule_tracking() RETURNS int LANGUAGE plpgsql SET search_path=gazi_ops,pg_catalog AS $$
DECLARE s record; n int:=0; minutes int;
BEGIN
 minutes:=greatest(30,least(1440,(SELECT value::text::int FROM settings WHERE key='tracking_minutes')));
 FOR s IN SELECT order_id FROM shipments JOIN orders ON siparis_no=order_id WHERE cancelled_at IS NULL AND kargo_durumu IN ('Kargolandı','İade') AND (last_sync IS NULL OR last_sync<now()-make_interval(mins=>minutes)) AND NOT EXISTS(SELECT 1 FROM jobs j WHERE j.order_id=shipments.order_id AND j.kind='track' AND j.state='failed' AND j.run_at>now()) LOOP
  PERFORM queue(s.order_id,'track');n:=n+1;
 END LOOP;RETURN n;
END $$;
CREATE FUNCTION claim_job() RETURNS SETOF jobs LANGUAGE plpgsql SET search_path=gazi_ops,pg_catalog AS $$
BEGIN
 WITH expired AS (UPDATE jobs SET state='failed',last_error='İş deneme sınırına ulaştı',lease_until=NULL WHERE state='running' AND lease_until<now() AND attempts>=5 RETURNING order_id,kind)
 INSERT INTO issues(order_id,kind,title) SELECT order_id,'integration:'||kind,'Kargo işi deneme sınırına ulaştı' FROM expired ON CONFLICT(order_id,kind) WHERE state='open' DO NOTHING;
 RETURN QUERY WITH picked AS (SELECT id FROM jobs WHERE attempts<5 AND ((state='queued' AND run_at<=now()) OR (state='running' AND lease_until<now())) ORDER BY run_at,id FOR UPDATE SKIP LOCKED LIMIT 1)
 UPDATE jobs j SET state='running',attempts=attempts+1,lease_until=now()+interval '5 minutes',lease_token=gen_random_uuid() FROM picked WHERE j.id=picked.id RETURNING j.*;
END $$;
CREATE FUNCTION finish_job(p_job bigint,p_lease uuid,p_result jsonb) RETURNS boolean LANGUAGE plpgsql SET search_path=gazi_ops,pg_catalog AS $$
DECLARE j jobs;o orders;s shipments;e jsonb;v_code int;v_at timestamptz;v_reference text;v_label jsonb;
BEGIN
 SELECT * INTO j FROM jobs WHERE id=p_job AND state='running' AND lease_token=p_lease AND lease_until>now() FOR UPDATE;
 IF j.id IS NULL THEN RETURN false; END IF;
 SELECT * INTO o FROM orders WHERE siparis_no=j.order_id FOR UPDATE;
 SELECT * INTO s FROM shipments WHERE order_id=j.order_id;
 IF j.kind IN ('create','track','label') THEN
  v_reference:=coalesce(nullif(p_result->>'reference',''),s.reference);
  IF v_reference IS NULL THEN RAISE EXCEPTION 'Kargo referansı eksik'; END IF;
  IF j.kind='create' AND nullif(p_result->>'tracking','') IS NULL THEN RAISE EXCEPTION 'Kargo servisi gönderi numarası doğrulamadı'; END IF;
  IF j.kind='create' AND o.kargo_durumu<>'Hazırlandı' THEN RAISE EXCEPTION 'Sipariş artık kargoya hazır değil'; END IF;
  v_code:=coalesce((p_result->>'status_code')::int,s.status_code,1);v_at:=coalesce((p_result->>'state_at')::timestamptz,now());
  INSERT INTO shipments(order_id,reference,tracking,environment,status_code,state,state_at,last_sync,branch,branch_phone)
  VALUES(j.order_id,v_reference,nullif(p_result->>'tracking',''),coalesce(p_result->>'environment',s.environment),v_code,coalesce(p_result->>'state',s.state,'Gönderi hazırlandı'),v_at,now(),p_result->>'branch',p_result->>'branch_phone')
  ON CONFLICT(order_id) DO UPDATE SET reference=excluded.reference,tracking=coalesce(excluded.tracking,shipments.tracking),last_sync=now(),branch=coalesce(nullif(excluded.branch,''),shipments.branch),branch_phone=coalesce(nullif(excluded.branch_phone,''),shipments.branch_phone);
  IF (s.state_at IS NULL OR v_at>=s.state_at) AND (s.status_code IS DISTINCT FROM 5 OR v_code=5) AND o.kargo_durumu NOT IN ('İptal','Silindi') THEN
   UPDATE shipments SET status_code=v_code,state=coalesce(p_result->>'state',state),state_at=v_at WHERE order_id=j.order_id;
   UPDATE orders SET kargo_durumu=CASE WHEN v_code=5 THEN 'Tamamlandı' WHEN v_code=7 THEN 'İade' ELSE 'Kargolandı' END,version=version+1,updated_at=now() WHERE siparis_no=j.order_id AND kargo_durumu IS DISTINCT FROM CASE WHEN v_code=5 THEN 'Tamamlandı' WHEN v_code=7 THEN 'İade' ELSE 'Kargolandı' END;
  END IF;
  FOR e IN SELECT * FROM jsonb_array_elements(coalesce(p_result->'events','[]')) LOOP
   IF nullif(e->>'id','') IS NULL THEN RAISE EXCEPTION 'Kargo hareket kimliği eksik'; END IF;
   INSERT INTO events(order_id,event_key,title,occurred_at,payload) VALUES(j.order_id,'carrier:'||v_reference||':'||(e->>'id'),e->>'title',(e->>'at')::timestamptz,e) ON CONFLICT(order_id,event_key) DO NOTHING;
  END LOOP;
  v_label:=p_result->'label';
  IF v_label IS NOT NULL THEN
   IF jsonb_array_length(coalesce(v_label->'barcodes','[]'))<>o.kargo_adet OR (SELECT count(DISTINCT b->>'barcode') FROM jsonb_array_elements(v_label->'barcodes') b)<>o.kargo_adet THEN RAISE EXCEPTION 'Paket barkod sayısı doğrulanamadı'; END IF;
   INSERT INTO labels(order_id,zpl,pdf_base64,barcodes) VALUES(j.order_id,v_label->>'zpl',v_label->>'pdf_base64',v_label->'barcodes') ON CONFLICT(order_id) DO UPDATE SET zpl=coalesce(excluded.zpl,labels.zpl),pdf_base64=coalesce(excluded.pdf_base64,labels.pdf_base64),barcodes=excluded.barcodes,updated_at=now();
  END IF;
  -- Only the current accepted shipment state determines support, never an out-of-order result.
  SELECT * INTO s FROM shipments WHERE order_id=j.order_id;
  IF s.status_code IN (6,7,8) THEN
   INSERT INTO issues(order_id,kind,title) VALUES(j.order_id,'carrier',coalesce(s.state,'Kargo müdahale gerektiriyor')) ON CONFLICT(order_id,kind) WHERE state='open' DO UPDATE SET title=excluded.title;
  ELSIF s.status_code=5 THEN UPDATE issues SET state='resolved',resolution='Teslim edildi',resolved_at=now() WHERE order_id=j.order_id AND kind='carrier' AND state='open'; END IF;
  IF nullif(p_result->>'movement_error','') IS NOT NULL THEN
   INSERT INTO issues(order_id,kind,title) VALUES(j.order_id,'movement','Durum alındı; hareket servisi yanıt vermedi') ON CONFLICT(order_id,kind) WHERE state='open' DO NOTHING;
  ELSE UPDATE issues SET state='resolved',resolution='Hareket geçmişi alındı',resolved_at=now() WHERE order_id=j.order_id AND kind='movement' AND state='open'; END IF;
  IF j.kind='create' THEN PERFORM queue(j.order_id,'reaction','{"emoji":"🚚"}'); END IF;
 ELSIF j.kind='cancel' THEN
  IF coalesce((p_result->>'cancelled')::boolean,false)=false THEN RAISE EXCEPTION 'DHL iptali doğrulanmadı'; END IF;
  UPDATE shipments SET cancelled_at=now() WHERE order_id=j.order_id;
  UPDATE orders SET kargo_durumu='İptal',iptal_nedeni=j.payload->>'reason',iptal_tarihi=now(),version=version+1,updated_at=now() WHERE siparis_no=j.order_id;PERFORM audit(j.order_id,'DHL gönderi iptali doğrulandı');
 ELSIF j.kind='codes' THEN
  IF (p_result->>'city_code')::int IS NULL OR (p_result->>'district_code')::int IS NULL THEN RAISE EXCEPTION 'İl/ilçe kodları bulunamadı'; END IF;
  UPDATE orders SET sehir_kodu=(p_result->>'city_code')::int,ilce_kodu=(p_result->>'district_code')::int,version=version+1,updated_at=now() WHERE siparis_no=j.order_id AND kargo_durumu IN ('Bekliyor','Hazırlandı');PERFORM audit(j.order_id,'İl/ilçe kodları doğrulandı');
 END IF;
 UPDATE jobs SET state='done',lease_until=NULL,last_error=NULL WHERE id=p_job;
 UPDATE issues SET state='resolved',resolution='Servis işlemi tamamlandı',resolved_at=now() WHERE order_id=j.order_id AND kind='integration:'||j.kind AND state='open';
 INSERT INTO events(order_id,event_key,title,payload) VALUES(j.order_id,'worker:'||p_job,'Servis işlemi tamamlandı: '||j.kind,jsonb_build_object('job_id',p_job)) ON CONFLICT DO NOTHING;
 RETURN true;
END $$;
CREATE FUNCTION fail_job(p_job bigint,p_lease uuid,p_error text) RETURNS boolean LANGUAGE plpgsql SET search_path=gazi_ops,pg_catalog AS $$
DECLARE j jobs;
BEGIN
 UPDATE jobs SET state=CASE WHEN attempts>=5 THEN 'failed' ELSE 'queued' END,run_at=now()+least(1800,30*power(2,attempts))*interval '1 second',lease_until=NULL,last_error=left(p_error,500) WHERE id=p_job AND state='running' AND lease_token=p_lease AND lease_until>now() RETURNING * INTO j;
 IF j.id IS NULL THEN RETURN false; END IF;
 INSERT INTO issues(order_id,kind,title) VALUES(j.order_id,'integration:'||j.kind,left(p_error,500)) ON CONFLICT(order_id,kind) WHERE state='open' DO UPDATE SET title=excluded.title;
 RETURN true;
END $$;
-- Private schema, unreachable from Supabase's default public REST schema.
-- Runtime credentials are server-side only. No anon/authenticated table grants.
DO $$ DECLARE t record; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='gazi_ops' LOOP EXECUTE format('ALTER TABLE gazi_ops.%I ENABLE ROW LEVEL SECURITY',t.tablename); END LOOP; END $$;
REVOKE ALL ON SCHEMA gazi_ops FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA gazi_ops FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA gazi_ops FROM PUBLIC;
COMMIT;
